COPY crm.assessments ("id", "person_id", "consultation_id", "visit", "amendment", "ref", "amends", "kind", "status", "answers", "open_sections", "notes", "recorded_by", "started_at", "updated_at", "finalised_at") FROM stdin;
a55e5100-0000-4000-8000-000000000001	ca466ca3-fa88-4508-ba1c-863b048d9a9c	d1f0e100-0000-4000-8000-000000000001	0	0	sofiadsouza0_0	\N	first_visit	final	{"dob": "1992-03-14", "sex": "Female", "ssb": "Occasional — a cola on a long shift, maybe once a fortnight", "name": "Sofia D'Souza", "ncpt": "NI-1.3", "email": "sofia.dsouza@example.com", "fluid": "Under a litre most days. Forgets on shift. Fills the bottle and does not drink it.", "likes": "Dal, paneer, idli, dosa, upma, poha, rajma, chana, fruit, curd, coconut chutney", "phone": "+919833077701", "sleep": "Broken. Five to six hours on shift weeks, catches up on days off. Room is bright in the morning.", "bowels": "Constipated on shift weeks — two or three days between. Normal on days off.", "nausea": "Occasional reflux if she eats late and lies down straight after. No vomiting.", "reason": "Tired all the time and putting on weight since the shift pattern changed two years ago. Wants to feel steady through a night shift without living on biscuits.", "stress": "High during shift weeks. Settles within a day of finishing.", "alcohol": "Rarely — a glass of wine perhaps twice a year", "chewing": "No trouble. Full dentition.", "consent": "Yes", "kitchen": "Full kitchen, confident cook, pressure cooker and a mixer. Limited time on shift days.", "pattern": "Vegetarian", "smoking": "Never", "support": "Mother is willing to cook differently. Husband eats whatever is made.", "activity": "Nothing planned. On her feet the whole shift — perhaps 12,000 steps — then too tired to walk on days off.", "appetite": "Variable — no appetite at all on the first night shift, ravenous by the third", "avoiding": "Milk in tea since the bloating started. Uses black tea now.", "barriers": "Time on shift days, and the staff room having nothing in it but biscuits. Says she will not cook separately from the family.", "bloating": "Most evenings, worse after bread and after milky tea", "caffeine": "Five to six teas a day, all with two sugars. Black since the bloating started.", "carb_fat": "Lower-GI carbohydrate spread across four occasions. Fat around 30% of energy.", "cravings": "Sweet things around 3pm and again at midnight", "cultural": "No beef or pork in the house. Fasts on some Fridays — fruit and water only.", "dislikes": "Bitter gourd, ridge gourd, brinjal", "fluid_ml": "2500", "handouts": "Portion guide, and the lower-GI swap list", "language": "English", "portions": "Rice portions large — two to three cups at a sitting. Chapatis two to three.", "progress": "First visit — nothing to compare against yet.", "referral": "Her GP, after the last fasting glucose", "snacking": "Biscuits at every tea. Says it is boredom and tiredness rather than hunger. Worst between 2am and 4am when the ward is quiet.", "adherence": "First visit — no previous plan.", "diet_type": "Lower-GI vegetarian, dairy-limited", "dietitian": "Khadija", "education": "Carbohydrate spread and why it matters for PCOS. Why breakfast matters on a shift pattern. Reading a portion of rice by eye.", "follow_up": "2026-09-13", "food_recs": "Swap two of the daily teas for water or a small buttermilk. Reduce rice to one cup and make up the volume with vegetables and dal. Keep roasted chana or nuts in her bag. Add a fruit with the mid-shift snack for the iron.", "meal_plan": "Four eating occasions rather than two, arranged around the shift rather than the clock. Something with protein at every one. A planned snack she takes in with her, so the staff room biscuits stop being the only option at 3am.", "pes_signs": "As evidenced by 6.4 kg weight gain in eighteen months, waist 94 cm, BMI 29.1, and a 24-hour recall showing no intake before 11am followed by 2.5 cups of rice at 2pm", "protein_g": "85", "readiness": "7", "sedentary": "Forty minutes each way in the car on off days. Sits through handover twice a shift.", "who_cooks": "Mother cooks on weekdays; Sofia cooks at weekends", "conditions": "PCOS, diagnosed 2021 — irregular cycles, acne along the jaw. Borderline raised fasting glucose at the last check. Mild iron-deficiency anaemia in 2023.", "discomfort": "Milk in tea reliably causes cramps within the hour. Curd in small amounts is fine. Large rice portions leave her heavy and sleepy.", "eating_out": "Twice a week, usually after a night shift. Pav bhaji or a dosa near the hospital.", "occupation": "Staff nurse, rotating shifts — three nights on, three off", "past_diets": "Tried a keto plan from an app in 2023 — lost 4 kg, gained 6 back in three months. Says she cannot keep anything up that stops her eating with the family.", "recall_24h": "Nothing before 11am. Tea with two biscuits at 11. Rice, dal and a potato sabzi about 2pm — two and a half cups of rice. Tea and three more biscuits at 5. Two chapatis with sabzi around 9pm. A piece of chocolate before bed.", "counselling": "Motivational interviewing — she set the four-occasion goal herself", "medications": "Metformin 500 mg twice daily, with meals. Combined oral contraceptive.", "pes_problem": "Excessive energy intake with irregular timing", "supplements": "None currently. Took an iron supplement for three months in 2023 and stopped.", "typical_day": "Skips breakfast entirely on shift days. Eats properly only in the evening. Grazes on whatever is in the staff room overnight — usually biscuits or namkeen.", "meal_pattern": "Two proper meals, both late. Breakfast almost never happens. No planned snack.", "past_history": "Appendicectomy 2014. No other surgery. Two uncomplicated pregnancies, 2018 and 2021.", "pes_etiology": "Related to shift work, skipped breakfast, and reliance on sweet snacks for energy overnight", "prescription": "1650 kcal, protein 85 g, carbohydrate spread evenly across four occasions, fibre 30 g", "food_security": "No constraint. Happy to buy nuts, fruit and curd weekly.", "drug_allergies": "None known.", "family_history": "Mother type 2 diabetes at 52. Father hypertension. Maternal grandmother diabetes.", "food_allergies": "Cow's milk — bloating, cramps and loose stool within an hour. Not anaphylactic. Tolerates small amounts of curd.", "goal_weight_kg": "68", "measure_method": "Clinic scale", "activity_factor": "1.375 light", "supplement_recs": "Vitamin D 60,000 IU weekly for eight weeks — GP has already advised this", "usual_weight_kg": "70", "deficiency_signs": "Nails brittle and ridged. Hair shedding more than usual since the spring. No angular stomatitis.", "condition_targets": "Even carbohydrate distribution for PCOS and the raised fasting glucose. Fibre 30 g for the constipation. Iron-rich foods with vitamin C at the same meal."}	[]	Bright, motivated, and completely defeated by the rota. The plan has to survive a night shift or it will not survive at all.	Khadija	2026-07-26 17:11:27.772532+05:30	2026-07-27 17:11:27.772532+05:30	2026-07-27 17:11:27.772532+05:30
